import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_sigmoid_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T> struct VecTraits;

template <>
struct VecTraits<float> {
  using T = float;
  static constexpr int VecSize = 4;
  using VecType = float4;
  __device__ static VecType apply(VecType v) {
    v.x = 1.0f / (1.0f + expf(-v.x));
    v.y = 1.0f / (1.0f + expf(-v.y));
    v.z = 1.0f / (1.0f + expf(-v.z));
    v.w = 1.0f / (1.0f + expf(-v.w));
    return v;
  }
  __device__ static T scalar(T x) {
    return 1.0f / (1.0f + expf(-x));
  }
};

template <>
struct VecTraits<double> {
  using T = double;
  static constexpr int VecSize = 2;
  using VecType = double2;
  __device__ static VecType apply(VecType v) {
    v.x = 1.0 / (1.0 + exp(-v.x));
    v.y = 1.0 / (1.0 + exp(-v.y));
    return v;
  }
  __device__ static T scalar(T x) {
    return 1.0 / (1.0 + exp(-x));
  }
};

template <typename T>
__global__ void sigmoid_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t N)
{
  using Traits = VecTraits<T>;
  constexpr int VecSize = Traits::VecSize;
  using VecType = typename Traits::VecType;

  constexpr int Threads = 256;
  const int64_t tile_elems = (int64_t)Threads * VecSize;
  const int64_t base = (int64_t)blockIdx.x * tile_elems;

  // Represent full tensors with CUTE
  Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N));
  Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N));

  // Tile per-block
  Tensor gX = local_tile(mX, make_shape(Int<Threads * VecSize>{}), make_coord(blockIdx.x));
  Tensor gY = local_tile(mY, make_shape(Int<Threads * VecSize>{}), make_coord(blockIdx.x));

  // Partition per-thread: contiguous VecSize chunk each
  Tensor tX = local_tile(gX, make_shape(Int<VecSize>{}), make_coord((int)threadIdx.x));
  Tensor tY = local_tile(gY, make_shape(Int<VecSize>{}), make_coord((int)threadIdx.x));

  const int64_t thread_start = base + (int64_t)threadIdx.x * VecSize;

  if (thread_start + VecSize <= N) {
    // Fast vectorized path
    Tensor tX_v = recast<VecType>(tX);
    Tensor tY_v = recast<VecType>(tY);
    VecType v = tX_v(0);
    v = Traits::apply(v);
    tY_v(0) = v;
  } else {
    // Boundary path, element-wise
    #pragma unroll
    for (int i = 0; i < VecSize; ++i) {
      int64_t idx = thread_start + i;
      if (idx < N) {
        T val = tX(i);
        tY(i) = Traits::scalar(val);
      }
    }
  }
}

torch::Tensor cute_sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t N = x_c.numel();
  if (N == 0) return y;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  AT_DISPATCH_FLOATING_TYPES(x_c.scalar_type(), "cute_sigmoid_forward", ([&] {
    constexpr int Threads = 256;
    int VecSize = VecTraits<scalar_t>::VecSize;
    int64_t tile_elems = (int64_t)Threads * VecSize;
    int64_t grid = (N + tile_elems - 1) / tile_elems;

    dim3 dimBlock(Threads);
    dim3 dimGrid((unsigned int)grid);

    sigmoid_kernel<scalar_t><<<dimGrid, dimBlock, 0, stream>>>(
        x_c.data_ptr<scalar_t>(),
        y.data_ptr<scalar_t>(),
        N
    );
  }));

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "cute_sigmoid_forward launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

cute_sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include", "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_sigmoid_forward(x)

